import * as rental from "host/rental";
import * as organizer from "host/organizer";
import * as text from "std/string";

function asciiLower(value: string): string {
    let upper: string = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let lower: string = "abcdefghijklmnopqrstuvwxyz";
    let result: string = "";
    for (let scalar: string of value) {
        let replacement: string = scalar;
        for (let index: int = 0; index < 26; index = index + 1) {
            if (scalar === text.substring(upper, index, index + 1)) {
                replacement = text.substring(lower, index, index + 1);
            }
        }
        result = result + replacement;
    }
    return result;
}

function decimal(value: int): string {
    let digits: string = "0123456789";
    if (value === 0) {
        return "0";
    }
    let result: string = "";
    let remaining: int = value;
    while (remaining > 0) {
        let quotient: int = remaining / 10;
        let digit: int = remaining - quotient * 10;
        result = text.substring(digits, digit, digit + 1) + result;
        remaining = quotient;
    }
    return result;
}

function euroPrice(cents: int): string {
    let euros: int = cents / 100;
    let remainder: int = cents - euros * 100;
    let fraction: string = decimal(remainder);
    if (remainder < 10) {
        fraction = "0" + fraction;
    }
    return "€" + decimal(euros) + "." + fraction;
}

function makeState(previous: State, quantity: int, budgetCents: int, search: string, sourceRows: RentalOption[], selectedId: string | null, loaded: boolean, loading: boolean, preparing: boolean, prepared: boolean, error: string, prepareFailure: boolean, reference: string): State {
    let quantityError: string = "";
    let budgetError: string = "";
    if (quantity < 1 || quantity > 8) {
        quantityError = "Choose a quantity from 1 to 8.";
    }
    if (budgetCents < 0 || budgetCents > 100000) {
        budgetError = "Enter a total budget from 0 to 100000 cents.";
    }
    let valid: boolean = quantityError === "" && budgetError === "";
    let editable: boolean = !loading && !preparing;
    let rows: RentalOption[] = [];
    let selectionExists: boolean = false;
    for (let row: RentalOption of sourceRows) {
        let selected: boolean = false;
        if (selectedId !== null) {
            selected = row.id === selectedId;
        }
        if (selected) {
            selectionExists = true;
        }
        let copied: RentalOption = {
            id: row.id,
            title: row.title,
            detail: row.detail,
            price: row.price,
            totalCents: row.totalCents,
            available: row.available,
            selected: selected,
            enabled: editable && valid
        };
        rows[rows.length] = copied;
    }
    return {
        quantity: quantity,
        budgetCents: budgetCents,
        search: search,
        periodStart: previous.periodStart,
        periodEnd: previous.periodEnd,
        quantityError: quantityError,
        budgetError: budgetError,
        valid: valid,
        editable: editable,
        canLoad: valid && editable,
        canPrepare: valid && editable && loaded && selectionExists && !prepared,
        rows: rows,
        selectedId: selectedId,
        loaded: loaded,
        loading: loading,
        preparing: preparing,
        prepared: prepared,
        empty: loaded && rows.length === 0,
        error: error,
        hasError: error !== "",
        prepareFailure: prepareFailure,
        reviewReference: reference
    };
}

function unchanged(state: State): State {
    return makeState(state, state.quantity, state.budgetCents, state.search, state.rows, state.selectedId, state.loaded, state.loading, state.preparing, state.prepared, state.error, state.prepareFailure, state.reviewReference);
}

export class RentalOption {
    id: string = "";
    title: string = "";
    detail: string = "";
    price: string = "";
    totalCents: int = 0;
    available: int = 0;
    selected: boolean = false;
    enabled: boolean = true;
}

export class State {
    quantity: int = 1;
    budgetCents: int = 2000;
    search: string = "";
    periodStart: string = "2026-10-10T16:00:00Z";
    periodEnd: string = "2026-10-10T22:00:00Z";
    quantityError: string = "";
    budgetError: string = "";
    valid: boolean = true;
    editable: boolean = true;
    canLoad: boolean = true;
    canPrepare: boolean = false;
    rows: RentalOption[] = [];
    selectedId: string | null = null;
    loaded: boolean = false;
    loading: boolean = false;
    preparing: boolean = false;
    prepared: boolean = false;
    empty: boolean = false;
    error: string = "";
    hasError: boolean = false;
    prepareFailure: boolean = false;
    reviewReference: string = "";
}

export class ChangeQuantity {
    value: int = 1;
}

export class ChangeBudget {
    value: int = 2000;
}

export class ChangeSearch {
    value: string = "";
}

export class Pick {
    value: string = "";
}

export class Load {}

export class Loaded {
    rows: RentalOption[] = [];
    error: string = "";
}

export class Prepare {}

export class Prepared {
    success: boolean = false;
    reference: string = "";
    error: string = "";
}

export function main(): null {
    return null;
}

export function initialState(): State {
    return {};
}

// @ui-update
export function changeQuantity(state: State, action: ChangeQuantity): State {
    if (!state.editable) {
        return unchanged(state);
    }
    let rows: RentalOption[] = [];
    return makeState(state, action.value, state.budgetCents, state.search, rows, null, false, false, false, false, "", false, "");
}

// @ui-update
export function changeBudget(state: State, action: ChangeBudget): State {
    if (!state.editable) {
        return unchanged(state);
    }
    let rows: RentalOption[] = [];
    return makeState(state, state.quantity, action.value, state.search, rows, null, false, false, false, false, "", false, "");
}

// @ui-update
export function changeSearch(state: State, action: ChangeSearch): State {
    if (!state.editable) {
        return unchanged(state);
    }
    let rows: RentalOption[] = [];
    return makeState(state, state.quantity, state.budgetCents, action.value, rows, null, false, false, false, false, "", false, "");
}

// @ui-update
export function pick(state: State, action: Pick): State {
    if (!state.editable || !state.valid) {
        return unchanged(state);
    }
    let selectedId: string | null = null;
    for (let row: RentalOption of state.rows) {
        if (row.id === action.value && row.enabled) {
            selectedId = action.value;
        }
    }
    if (selectedId === null) {
        return unchanged(state);
    }
    return makeState(state, state.quantity, state.budgetCents, state.search, state.rows, selectedId, state.loaded, false, false, false, "", false, "");
}

// @ui-update
export function startLoad(state: State, action: Load): State {
    if (!state.canLoad) {
        return unchanged(state);
    }
    let rows: RentalOption[] = [];
    return makeState(state, state.quantity, state.budgetCents, state.search, rows, null, false, true, false, false, "", false, "");
}

// @ui-effect
export async function loadOptions(state: State, action: Load): Loaded {
    let rows: RentalOption[] = [];
    if (!state.valid || state.preparing) {
        return { rows: rows, error: "Enter valid inputs before loading options." };
    }
    try {
        let records: table[] = await rental.equipment(state.periodStart, state.periodEnd);
        let search: string = asciiLower(text.trim(state.search));
        for (let record: table of records) {
            let id: string = record.id;
            let title: string = record.name;
            let specification: string = record.specification;
            let cents: int = record.cents;
            let available: int = record.available;
            let searchable: string = asciiLower(title + " " + specification);
            let matchesRequirement: boolean = text.contains(searchable, "boom") && text.contains(searchable, "stand");
            let matchesSearch: boolean = search === "" || text.contains(searchable, search);
            if (matchesRequirement && matchesSearch && available >= state.quantity && cents >= 0) {
                if (cents <= state.budgetCents / state.quantity) {
                    let totalCents: int = cents * state.quantity;
                    let option: RentalOption = {
                        id: id,
                        title: title,
                        detail: specification,
                        price: euroPrice(totalCents),
                        totalCents: totalCents,
                        available: available,
                        selected: false,
                        enabled: true
                    };
                    rows[rows.length] = option;
                }
            }
        }
        return { rows: rows, error: "" };
    } catch (e) {
        let emptyRows: RentalOption[] = [];
        return { rows: emptyRows, error: "Unable to load rental options: " + e.message };
    }
}

// @ui-update
export function finishLoad(state: State, action: Loaded): State {
    if (!state.loading) {
        return unchanged(state);
    }
    if (action.error !== "") {
        let rows: RentalOption[] = [];
        return makeState(state, state.quantity, state.budgetCents, state.search, rows, null, false, false, false, false, action.error, false, "");
    }
    return makeState(state, state.quantity, state.budgetCents, state.search, action.rows, null, true, false, false, false, "", false, "");
}

// @ui-update
export function startPrepare(state: State, action: Prepare): State {
    if (!state.canPrepare) {
        return unchanged(state);
    }
    return makeState(state, state.quantity, state.budgetCents, state.search, state.rows, state.selectedId, state.loaded, false, true, false, "", false, "");
}

// @ui-effect
export async function prepareForReview(state: State, action: Prepare): Prepared {
    if (!state.valid || state.loading || state.prepared) {
        return { success: false, reference: "", error: "Select a qualifying option before preparing for review." };
    }
    let selectedId: string | null = state.selectedId;
    let selected: RentalOption | null = null;
    for (let row: RentalOption of state.rows) {
        if (selectedId !== null) {
            if (row.id === selectedId) {
                selected = row;
            }
        }
    }
    let chosen: RentalOption | null = selected;
    if (chosen !== null) {
        let title: string = chosen.title;
        let price: string = euroPrice(chosen.totalCents);
        let detail: string = "Item " + chosen.id + ":" + decimal(state.quantity) + "; from " + state.periodStart + "; until " + state.periodEnd;
        try {
            let result: table = await organizer.stage("rental", "host/rental", title, detail, price, state.periodEnd);
            let staged: boolean = result.staged;
            let reference: string = result.reference;
            if (!staged) {
                return { success: false, reference: "", error: "Local preparation did not complete. Try again." };
            }
            return { success: true, reference: reference, error: "" };
        } catch (e) {
            return { success: false, reference: "", error: "Unable to prepare for native review: " + e.message };
        }
    } else {
        return { success: false, reference: "", error: "Select a qualifying option before preparing for review." };
    }
}

// @ui-update
export function finishPrepare(state: State, action: Prepared): State {
    if (!state.preparing) {
        return unchanged(state);
    }
    return makeState(state, state.quantity, state.budgetCents, state.search, state.rows, state.selectedId, state.loaded, false, false, action.success, action.error, !action.success, action.reference);
}

