import * as app from "./experience";
import * as ui from "./platform.dealui-pack";

// @ui-root
export view RentalShortlist(state: app.State): View {
    ui.Column() {
        ui.Hero(value: "Rental shortlist")
        ui.Text(value: "Boom stand · Adjustable boom")
        ui.Text(value: "Change the quantity and total budget to refine your shortlist. Start with 1 unit and 2000 cents to include the stand and package when available.")
        ui.Text(value: "Rental period: 2026-10-10T16:00:00Z to 2026-10-10T22:00:00Z")
        ui.Card() {
            ui.IntField(value: state.quantity, label: "Quantity", minimum: 0, maximum: 9, step: 1, enabled: state.editable, supporting: "Choose 1 to 8 units. Changing quantity clears the shortlist and preparation.", error: state.quantityError, onChange: action app.ChangeQuantity { value: payload }, accessibilityLabel: "Quantity")
            ui.IntField(value: state.budgetCents, label: "Total budget in cents", minimum: 0, maximum: 100000, step: 100, enabled: state.editable, supporting: "Budget for all units, not per unit. 2000 cents is €20.00. Allowed range: 0 to 100000 cents.", error: state.budgetError, onChange: action app.ChangeBudget { value: payload }, accessibilityLabel: "Budget")
            ui.SearchField(value: state.search, label: "Search", multiline: false, enabled: state.editable, supporting: "Optional substring of the name or specification. Spaces at the ends and ASCII letter case are ignored.", error: "", onChange: action app.ChangeSearch { value: payload }, accessibilityLabel: "Search")
            ui.Button(text: "Load options", enabled: state.canLoad, onClick: action app.Load {}, accessibilityLabel: "Load options")
        }
        When(state.loading) {
            ui.Progress(label: "Loading")
        }
        When(state.preparing) {
            ui.Progress(label: "Preparing for native review")
        }
        When(state.hasError) {
            When(state.prepareFailure) {
                ui.Failure(text: state.error, onRetry: action app.Prepare {}, accessibilityLabel: "Retry preparation for native review")
            } Else {
                ui.Failure(text: state.error, onRetry: action app.Load {}, accessibilityLabel: "Retry loading rental options")
            }
        }
        When(state.loaded) {
            ui.Section(title: "Qualifying options", summary: "Prices are total euro prices for your selected quantity. Options must match boom and stand, have sufficient availability, and fit your total budget.") {
                When(state.empty) {
                    ui.Text(value: "No qualifying options")
                    ui.Text(value: "Try reducing quantity, increasing the total budget, or clearing the search, then load options again.")
                } Else {
                    ForEach(state.rows, row: app.RentalOption, key: row.id) {
                        ui.Option(value: row.id, title: row.title, detail: row.detail, price: row.price, meta: "Total for all requested units", selected: row.selected, enabled: row.enabled, onSelect: action app.Pick { value: payload }, accessibilityLabel: row.title)
                    }
                    ui.Button(text: "Prepare for review", enabled: state.canPrepare, onClick: action app.Prepare {}, accessibilityLabel: "Prepare for review")
                }
            }
        } Else {
            When(state.loading) {
                ui.Text(value: "Checking the catalogue for the disclosed rental period.")
            } Else {
                When(state.hasError) {
                    ui.Text(value: "No catalogue results are available. Retry loading options.")
                } Else {
                    ui.Text(value: "Edit quantity and total budget, then load options. The catalogue is read only when you choose Load options.")
                }
            }
        }
        When(state.prepared) {
            ui.Notice(text: "Prepared for native review", tone: "info")
        }
        ui.Text(value: "This shortlist only reads options and prepares a local review descriptor. Nothing is reserved; native confirmation stays outside this view.")
    }
}
